<?php
require __DIR__.'/../database/runtime.php';$method=$_SERVER['REQUEST_METHOD'];$action=(string)($_GET['action']??'status');
if($method==='GET'){$u=requireUser();if($u['role']==='admin'){$rows=$pdo->query("SELECT r.id,r.organization_name,r.phone,r.status,r.created_at,u.first_name,u.last_name,u.email FROM organizer_requests r JOIN users u ON u.id=r.user_id ORDER BY FIELD(r.status,'pending','approved','rejected'),r.created_at DESC")->fetchAll();reply($rows);}$q=$pdo->prepare('SELECT organization_name,phone,status,created_at FROM organizer_requests WHERE user_id=?');$q->execute([$u['id']]);reply($q->fetch()?:['status'=>$u['role']==='organizer'?'approved':'none']);}
if($method!=='POST')reply(['error'=>'Méthode invalide.'],405);$d=body();
if($action==='request'){$u=requireUser();rateLimit('organizer-request:'.$u['id'],3,3600);if($u['role']!=='user')reply(['error'=>'Seuls les comptes participants peuvent demander à devenir organisateurs.'],409);$name=trim((string)($d['organizationName']??''));$phone=trim((string)($d['phone']??''));if($name===''||$phone==='')reply(['error'=>'Indiquez le nom de votre organisation et un téléphone.'],422);$q=$pdo->prepare("INSERT INTO organizer_requests(user_id,organization_name,phone,status) VALUES(?,?,?,'pending') ON DUPLICATE KEY UPDATE organization_name=VALUES(organization_name),phone=VALUES(phone),status='pending',reviewed_by=NULL,reviewed_at=NULL");$q->execute([$u['id'],$name,substr($phone,0,30)]);reply(['status'=>'pending']);}
if($action==='review'){$admin=requireAdmin();$id=(int)($d['requestId']??0);$decision=(string)($d['decision']??'');if(!$id||!in_array($decision,['approve','reject'],true))reply(['error'=>'Décision invalide.'],422);$pdo->beginTransaction();$q=$pdo->prepare('SELECT user_id,status FROM organizer_requests WHERE id=? FOR UPDATE');$q->execute([$id]);$r=$q->fetch();if(!$r||$r['status']!=='pending'){$pdo->rollBack();reply(['error'=>'Cette demande est introuvable ou a déjà été traitée.'],409);}$status=$decision==='approve'?'approved':'rejected';$pdo->prepare('UPDATE organizer_requests SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([$status,$admin['id'],$id]);$pdo->prepare('UPDATE users SET role=? WHERE id=?')->execute([$decision==='approve'?'organizer':'user',$r['user_id']]);$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id) VALUES(?,?,?,?)')->execute([$admin['email'],'organizer.'.$status,'organizer_request',(string)$id]);$pdo->commit();reply(['status'=>$status]);}
reply(['error'=>'Action inconnue.'],404);
